                        }
                    }

                    public class SlackDecorator : NotifierDecorator
                    {
                        public SlackDecorator(INotifier inner) : base(inner) { }
                        public override void Send(string message)
                        {
                            base.Send(message);
                            Console.WriteLine($"Slack: {message}");
                        }
                    }

